package com.sky.handler;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MissingPathVariableException;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;

import com.sky.exception.BaseException;
import com.sky.result.Result;

import java.sql.SQLIntegrityConstraintViolationException;

@ExtendWith(MockitoExtension.class)
class GlobalExceptionHandlerTest {

    @InjectMocks
    private GlobalExceptionHandler globalExceptionHandler;

    @Test
    @DisplayName("正向测试：验证 BaseException 异常处理返回正确的错误信息")
    void testExceptionHandler_BaseException() {
        // Arrange
        BaseException baseException = new BaseException("业务异常信息");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(baseException);

        // Assert
        assertNotNull(result);
        assertNotEquals(1, result.getCode());
        assertEquals("业务异常信息", result.getMsg());
    }

    @Test
    @DisplayName("正向测试：验证 SQLIntegrityConstraintViolationException 中包含 Duplicate entry 时返回正确的错误信息")
    void testExceptionHandler_SQLExceptionWithDuplicateEntry() {
        // Arrange
        SQLIntegrityConstraintViolationException sqlException = new SQLIntegrityConstraintViolationException(
                "Duplicate entry 'test' for key 'idx_name'");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(sqlException);

        // Assert
        assertNotNull(result);
        assertNotEquals(1, result.getCode());
        assertTrue(result.getMsg().contains("test"));
        assertTrue(result.getMsg().contains("已存在"));
    }

    @Test
    @DisplayName("正向测试：验证 SQLIntegrityConstraintViolationException 中不包含 Duplicate entry 时返回未知错误")
    void testExceptionHandler_SQLExceptionWithoutDuplicateEntry() {
        // Arrange
        SQLIntegrityConstraintViolationException sqlException = new SQLIntegrityConstraintViolationException(
                "some other SQL error");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(sqlException);

        // Assert
        assertNotNull(result);
        assertNotEquals(1, result.getCode());
        assertEquals("未知错误", result.getMsg());
    }

    @Test
    @DisplayName("正向测试：验证 MissingPathVariableException 异常处理返回正确的错误信息")
    void testExceptionHandler_MissingPathVariableException() {
        // Arrange
        MissingPathVariableException exception = new MissingPathVariableException("param", null);

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertNotEquals(1, result.getCode());
        assertEquals("请求参数绑定失败", result.getMsg());
    }

    @Test
    @DisplayName("正向测试：验证 HttpMessageNotReadableException 异常处理返回正确的错误信息")
    void testExceptionHandler_HttpMessageNotReadableException() {
        // Arrange
        HttpMessageNotReadableException exception = new HttpMessageNotReadableException("消息不可读", (Throwable) null);

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertNotEquals(1, result.getCode());
        assertEquals("请求数据格式错误", result.getMsg());
    }

    @Test
    @DisplayName("正向测试：验证 MethodArgumentTypeMismatchException 异常处理返回正确的错误信息")
    void testExceptionHandler_MethodArgumentTypeMismatchException() {
        // Arrange
        MethodArgumentTypeMismatchException exception = new MethodArgumentTypeMismatchException(
                "abc", Long.class, "id", null, null);

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertNotEquals(1, result.getCode());
        assertEquals("请求参数类型错误", result.getMsg());
    }

    @Test
    @DisplayName("正向测试：验证 NumberFormatException 异常处理返回正确的错误信息（修复新增）")
    void testExceptionHandler_NumberFormatException() {
        // Arrange
        NumberFormatException exception = new NumberFormatException("For input string: \"abc\"");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertNotEquals(1, result.getCode());
        assertEquals("请求参数格式错误", result.getMsg());
    }

    @Test
    @DisplayName("边界测试：验证原来导致异常的输入现在不再抛出异常（修复数字格式异常）")
    void testExceptionHandler_NumberFormatExceptionWithInvalidInput() {
        // Arrange: 这个测试验证修复前会导致原始异常的输入现在被正确处理
        NumberFormatException exception = new NumberFormatException("For input string: \"abc\"");

        // Act & Assert: 验证调用异常处理器不会抛出异常
        assertDoesNotThrow(() -> {
            Result<String> result = globalExceptionHandler.exceptionHandler(exception);
            assertNotNull(result);
            assertEquals("请求参数格式错误", result.getMsg());
        });
    }

    @Test
    @DisplayName("边界测试：验证空消息的 NumberFormatException 仍然能被正确处理")
    void testExceptionHandler_NumberFormatExceptionWithNullMessage() {
        // Arrange: 测试 null 消息的 NumberFormatException
        NumberFormatException exception = new NumberFormatException(null);

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertNotEquals(1, result.getCode());
        assertEquals("请求参数格式错误", result.getMsg());
    }

    @Test
    @DisplayName("边界测试：验证空字符串消息的 NumberFormatException 仍然能被正确处理")
    void testExceptionHandler_NumberFormatExceptionWithEmptyMessage() {
        // Arrange: 测试空字符串消息的 NumberFormatException
        NumberFormatException exception = new NumberFormatException("");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertNotEquals(1, result.getCode());
        assertEquals("请求参数格式错误", result.getMsg());
    }
}
